"""Emit a compiled table as a C initialiser.

The equivalence gate needs both implementations walking THE SAME TABLE. Anything
hand-transcribed into the test would be a third copy that can drift, and a drift
there would look exactly like an interpreter bug — the most expensive kind of
false positive this project can produce.

So the Python compiler emits the table and the C++ test includes it. One source,
two readers.
"""

from __future__ import annotations

from taskgraph.table import StateTable


def _u(v: int) -> str:
    return str(int(v))


def emit(table: StateTable, symbol: str = "TG_TABLE") -> str:
    n = table
    out: list[str] = []
    add = out.append

    add("/* GENERATED by taskgraph/emit/c_table.py — DO NOT EDIT.")
    add(" *")
    add(f" * spec:     {n.spec_id}")
    add(f" * hash:     {n.spec_hash}")
    add(f" * template: {n.template} v{n.template_version} ({n.template_hash})")
    add(" *")
    add(" * The equivalence gate needs both implementations walking the same table.")
    add(" * Hand-transcribing it into the test would be a third copy that can drift,")
    add(" * and a drift there looks exactly like an interpreter bug.")
    add(" */")
    add("")
    add("#include <TgInterpret.h>")
    add("")
    add("/*  Timing indices by name. A harness that rewrites a ramped entry -- which is")
    add(" *  how the stage schedule and the abstention escalator both work -- should")
    add(" *  address it by name. A magic number here would silently point at the wrong")
    add(" *  duration the moment a spec adds a timing entry above it. */")
    for i, tid in enumerate(n.timing_ids):
        add(f"#define TG_IDX_{tid.removeprefix('t_').upper()} {i}")
    add("")
    add(f"static const TgTable {symbol} = {{")

    add("  /* nodes */ {")
    for i, x in enumerate(n.nodes):
        strobe = f"0x{x.strobe:04X}"
        add(
            f"    {{{_u(x.type)}, {_u(x.dur_idx)}, {strobe}, {_u(x.watch_mask)}, "
            f"{_u(x.action_idx)}, {_u(x.action_count)}, {_u(x.edge_idx)}}},"
            f"  /* S{i:02d} {x.label} */"
        )
    add("  },")

    add("  /* edges */ {")
    for i, e in enumerate(n.edges):
        guard = f" [{e.guard_text}]" if e.guard_text else ""
        add(
            f"    {{{_u(e.trigger)}, {_u(e.guard)}, {_u(e.target)}, {_u(e.effect)}}},"
            f"  /* {i:2d}: {e.trigger}{guard} -> S{e.target:02d} */"
        )
    add("  },")

    add("  /* timing */ {" + ", ".join(_u(v) for v in n.timing) + "},")

    add("  /* actions */ {")
    for a in n.actions:
        add(f"    {{{_u(a.channel)}, {_u(a.op)}}},  /* {'set' if a.op else 'clear'} {a.channel_name} */")
    add("  },")

    add("  /* trialTypes */ {")
    for r in n.trial_types:
        stim = list(r.stimulus) + [255] * (4 - len(r.stimulus))
        add(
            f"    {{{_u(stim[0])}, {_u(stim[1])}, {_u(stim[2])}, {_u(stim[3])}, "
            f"{_u(r.target)}, {_u(r.weight)}, {_u(r.reward_line)}, {_u(r.reward_dur_idx)}}},"
            f"  /* {r.label} */"
        )
    add("  },")

    add("  /* ports */ {")
    for p in n.ports:
        add(
            f"    {{{_u(p.channel)}, {_u(p.reward_line)}, {_u(p.enter_code)}, "
            f"{_u(p.error_code)}, {_u(p.break_code)}, {_u(p.exit_code)}, "
            f"{_u(p.reward_code)}, {_u(p.reward_stop_code)}, {_u(p.reward_dur_idx)}, 0}},"
            f"  /* {p.name} */"
        )
    add("  },")

    add("  /* stimuli */ {")
    for s in n.stimuli:
        add(f"    {{{_u(s.emitter)}, 0, {_u(s.on_code)}}},  /* {s.name} */")
    add("  },")

    add("  /* stageRows */ {")
    for r in n.stage_rows:
        add(
            f"    {{{_u(r.at_trial)}, {_u(r.count)}, {_u(r.first_idx)}}},"
            f"  /* at trial {r.at_trial}: {r.count} rewrite(s) */"
        )
    add("  },")

    add("  /* timingSets */ {")
    for s in n.timing_sets:
        name = n.timing_ids[s.idx] if s.idx < len(n.timing_ids) else f"[{s.idx}]"
        add(f"    {{{_u(s.idx)}, 0, {_u(s.ms)}}},  /* {name} := {s.ms} ms */")
    add("  },")

    #: Zero means "the compiler could not bound this one" -- the watchdog falls
    #: back to its session ceiling there. Zero is safe as the sentinel because a
    #: node whose real bound is 0 ms cannot overrun anything.
    dwell = [d or 0 for d in n.max_dwell]
    add("  /* maxDwell */ {" + ", ".join(_u(v) for v in dwell) + "},")

    pins = list(n.watch_pins) + [255] * (8 - len(n.watch_pins))
    ports = list(n.watch_ports) + [255] * (8 - len(n.watch_ports))
    add("  /* watchPin  */ {" + ", ".join(_u(v) for v in pins) + "},")
    add("  /* watchPort */ {" + ", ".join(_u(v) for v in ports) + "},")

    #: Provenance comes BEFORE the counts, matching TgTable's field order -- which
    #: puts the uint32s where both toolchains align them identically. This is
    #: positional aggregate initialisation, so the order here is not cosmetic: a
    #: field moved in the struct and not here silently loads the wrong values.
    #:
    #: A compiled-in table has not been over the wire, so it has no CRC to carry
    #: and nothing verified it. It is `valid` because the compiler is the thing
    #: that would have signed it -- an uploaded table earns the same flag only
    #: after tgReceiveTable() checks the whole-table CRC.
    add(f"  /* specHash */ 0x{int(n.spec_hash[:8], 16):08X}, /* tableCrc */ 0,")
    add(
        f"  {_u(len(n.nodes))}, {_u(len(n.edges))}, {_u(len(n.timing))}, "
        f"{_u(len(n.actions))},"
    )
    add(
        f"  {_u(len(n.trial_types))}, {_u(len(n.ports))}, {_u(len(n.stimuli))}, "
        f"{_u(len(n.watch_pins))},"
    )
    add(f"  {_u(len(n.stage_rows))}, {_u(len(n.timing_sets))},")
    add("  /* valid */ true, /* _pad */ 0,")
    add("};")
    add("")
    return "\n".join(out)
